def cantor(x, y):
    return (x + y) * (x + y + 1) // 2 + y

def count_odd(M):
    count = 0
    for x in range(M):
        for y in range(M):
            val = cantor(x, y)
            if val % 2 != 0:
                count += 1
    return count

# Calculate for M=2 and M=3
N_M2 = count_odd(2)
N_M3 = count_odd(3)
print(f"N(M=2) = {N_M2}")
print(f"N(M=3) = {N_M3}")
